import {useState} from 'react';
import { BrowserRouter, Routes, Route, Link, useNavigate } from 'react-router-dom';
import axios from 'axios';

function getUserId() {
    let user_id = 0;

    axios.get('/api/user_id')
        .then(response => {
            console.log(response);
            user_id = response.user_id;
        })
        .catch(err => {
            console.error('Error:', err);
        });

    return user_id;
}


function NavigationButton({ path, title, is_api = false, http_method = "GET" }) {
    const navigate = useNavigate();

    const handleClick = () => {
        if(is_api) {
            axios.get(path)
                .then(response => {
                    console.log(response);
                })
                .catch(err => {
                    console.error('Error:', err);
                })
        } else {
            navigate(path);
        }
    };

    return (
        <button 
            className="Navigation-button"
            onClick={handleClick}
        >
            {title}
        </button>
    );
}


export function Home() {
    const user_id = getUserId();

    return (
        <div className="Button-holder">
            <NavigationButton
            title="Play"
            path="/hub"
            />

            { user_id > 0 ?
                (
                    <NavigationButton
                    title="View Profile"
                    color="#1a9c2a"
                    path="/profile"
                    />
                ) : (
                    <NavigationButton
                    title="Login"
                    color="#1a9c2a"
                    path="/login"
                    />
                )
            }


            <NavigationButton
            title="Leaderboard"
            color="#1a9c2a"
            path="/leaderboard"
            />

            <NavigationButton
            title="About"
            color="#aa3c3a"
            path="/about"
            />
        </div>
    )

}

export function Hub() {
    return (
        <div className="Button-holder">
            <NavigationButton
            title="Normal 180s"
            path="/play?game_mode=0"
            />

            <NavigationButton
            title="Normal 300s"
            path="/play?game_mode=1"
            />

            <NavigationButton
            title="Normal 600s"
            path="/play?game_mode=2"
            />
        </div>
    );
}

export function Login() {
    return (
        <div className="Button-holder">
            <NavigationButton
            title="Login With Google"
            path="/api/auth/google"
            />
        </div>
    );
}

export function Profile({ user_id }) {
    return (
        <>
        </>
    );
}

export function Leaderboard() {
    return <h1>Leaderboard</h1>
}

export function About() {
    return <h1>About</h1>
}
